CREATE TABLE IF NOT EXISTS label_model_configs (id SERIAL PRIMARY KEY,sku TEXT NOT NULL,apresentacao TEXT NOT NULL,label_type TEXT NOT NULL,template_path TEXT NOT NULL,template_sha256 TEXT NOT NULL,printer_allowlist TEXT NOT NULL,variable_map_json TEXT NOT NULL,pieces_source TEXT NOT NULL,ativo INTEGER NOT NULL DEFAULT 0,criado_em TIMESTAMP NOT NULL,UNIQUE(sku,apresentacao,label_type));
CREATE TABLE IF NOT EXISTS local_print_agents (id SERIAL PRIMARY KEY,agent_uuid TEXT NOT NULL UNIQUE,nome TEXT NOT NULL,station_code TEXT NOT NULL,token_hash TEXT,pairing_code_hash TEXT,pairing_expires_at TIMESTAMP,printer_name TEXT,printer_model TEXT,nicelabel_version TEXT,agent_version TEXT,status TEXT NOT NULL DEFAULT 'NAO_PAREADO',auto_print_enabled INTEGER NOT NULL DEFAULT 0,last_seen_at TIMESTAMP,criado_em TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS label_print_jobs (id SERIAL PRIMARY KEY,job_uuid TEXT NOT NULL UNIQUE,caixa_id INTEGER NOT NULL,label_type TEXT NOT NULL,op_id INTEGER,product TEXT NOT NULL,presentation TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 1,original_job_id INTEGER,model_config_id INTEGER NOT NULL,agent_id INTEGER,state TEXT NOT NULL,snapshot_json TEXT NOT NULL,template_sha256 TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,lease_token_hash TEXT,lease_expires_at TIMESTAMP,idempotency_key TEXT NOT NULL,justification TEXT,requested_by TEXT,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,reserved_at TIMESTAMP,sent_at TIMESTAMP,confirmed_at TIMESTAMP,invalidated_at TIMESTAMP,error_code TEXT,error_message TEXT,spool_reference TEXT,box_reversed INTEGER NOT NULL DEFAULT 0,UNIQUE(caixa_id,label_type,generation));
CREATE TABLE IF NOT EXISTS label_print_audit_events (id SERIAL PRIMARY KEY,entity_type TEXT NOT NULL,entity_uuid TEXT NOT NULL,action TEXT NOT NULL,actor TEXT,details_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS idx_label_jobs_state ON label_print_jobs(state,created_at);
CREATE INDEX IF NOT EXISTS idx_label_jobs_caixa ON label_print_jobs(caixa_id,created_at);
